mapper.update:
UPDATE family_invitation
SET status = 'CANCELED',
    updated_at = #{withdrawnAt}
WHERE inviter_member_id = #{memberId}
  AND status = 'PENDING'

UPDATE financial_connection
SET consent_status = 'REVOKED',
    revoked_at = #{withdrawnAt},
    updated_at = #{withdrawnAt}
WHERE connected_by_member_id = #{memberId}
  AND consent_status = 'ACTIVE'
